class Solution {
public:
    int snakesAndLadders(vector<vector<int>>& board) {
        int n = board.size();
        int target = n * n;
        vector<int> dist(target + 1, -1);
        queue<int> q;
        q.push(1);
        dist[1] = 0;

        while (!q.empty()) {
            int curr = q.front();
            q.pop();
            for (int dice = 1; dice <= 6; dice++) {
                int next = curr + dice;
                if (next > target) break;
                int r = (next - 1) / n;
                int c = (next - 1) % n;
                if (r % 2 == 1) c = n - 1 - c;
                int row = n - 1 - r;
                if (board[row][c] != -1) {
                    next = board[row][c];
                }
                if (dist[next] == -1) {
                    dist[next] = dist[curr] + 1;
                    if (next == target) return dist[next];
                    q.push(next);
                }
            }
        }
        return -1;
    }
};
